/// Seed `nano-generated/domain.ts` — the typed data-object accessor (ADR 0029 §6). It
/// starts with only `raw`/`close`; the `domaintypes` op regenerates it with one
/// `Table<T>` per table after the first schema change. Seeded (not overwritten
/// each run) so `@nanobpm/domain` resolves from scaffold, and the reified,
/// per-table version survives re-materialisation of the rest of the SDK.
const DOMAIN_TS_STUB: &str = r#"// AUTO-GENERATED by nanobpmn (ADR 0029 §4.1/§6) — the typed data-object layer.
// Seeded empty at scaffold; regenerated with one `Table<T>` per table after the
// first datasource schema change. Do not edit.
// eslint-disable
import { openDataSource, type DataSource, type Table } from "./data-sdk.ts";

export interface Domain {
  /** The underlying datasource handle — the raw-SQL escape hatch. */
  readonly raw: DataSource;
  /** Close the underlying connection. */
  close(): void;
}

/**
 * Open the App's default datasource as a typed domain. This seed exposes only
 * `raw`; once the schema is reified, each table gains a `Table<T>` accessor
 * (`db.orders.insert(...)`, `db.orders.get(id)`).
 */
export async function openDomain(source?: string): Promise<Domain> {
  const raw = await openDataSource(source);
  return { raw, close: () => raw.close() };
}

export type { Table };
"#;
/// The static typed-`defineWorker` wrapper (`workers.ts`, ADR 0033 §3). Written
/// verbatim on every SDK materialisation (it never changes with the schema): it
/// re-exports `worker-sdk.ts` and overrides `defineWorker` with a taskType-keyed
/// typed signature. Kept byte-identical to `emitWorkerBindingsRuntime()` in
/// `domain_types.ts` (the op writes the same file after a schema change).
const WORKERS_TS: &str = r#"// AUTO-GENERATED by nanobpmn (ADR 0033 §3): the typed `defineWorker`.
// Re-exports the worker SDK and overrides `defineWorker` with a taskType-keyed
// typed signature (job.variables, job.customHeaders + result typed from the
// worker's declared input/output/header contract). Erased to a pass-through at
// runtime. Do not edit.
// eslint-disable

import { defineWorker as defineWorkerRaw } from "./worker-sdk.ts";
import type { WorkerOptions } from "./worker-sdk.ts";
import type { WorkerInputs, WorkerOutputs, WorkerHeaders, WorkerTaskType, WorkerVars, WorkerHdrs } from "./worker-io.d.ts";

export * from "./worker-sdk.ts";

type InFor<K extends WorkerTaskType> = K extends keyof WorkerInputs ? WorkerInputs[K] : WorkerVars;
type OutFor<K extends WorkerTaskType> = K extends keyof WorkerOutputs ? WorkerOutputs[K] : WorkerVars;
type HdrFor<K extends WorkerTaskType> = K extends keyof WorkerHeaders ? WorkerHeaders[K] : WorkerHdrs;

/**
 * Typed `defineWorker`: `type` is constrained to the model's declared job types
 * (`WorkerTaskType`, ADR 0033 §3) so it autocompletes and rejects unknown jobs,
 * and the handler's `job.variables`, `job.customHeaders` + result are typed from
 * the worker's declared `inputType`/`outputType`/header keys. A declared job type
 * with no declared type falls back to WorkerVars / WorkerHdrs.
 */
export function defineWorker<K extends WorkerTaskType>(
  opts: { type: K } & WorkerOptions<InFor<K> & object, OutFor<K> & object, HdrFor<K> & object>,
): void {
  defineWorkerRaw(opts as unknown as WorkerOptions);
}
"#;
