// ---------------------------------------------------------------------------
// "Code-first workflow" template (ADR 0045) — the code-first dual of the
// model-first Urban scaffold. There is NO authored BPMN and none of the
// model-first `nano-generated/` machinery: the executable model is DERIVED from
// the workflow code by @nanobpm/workflow (ADR 0044) at deploy time. So this
// scaffold is a lean tree (see the early return in `create_project`).
// ---------------------------------------------------------------------------

/// Import map for a code-first project: the real published SDK (resolved via
/// `npm:` under Deno / `node_modules` under Node) plus a `start` task that runs
/// the entrypoint (which deploys the workflows and hosts a Worker).
const WORKFLOW_DENO_JSON: &str = r#"{
  "imports": {
    "@nanobpm/workflow": "npm:@nanobpm/workflow@^0.3.0",
    "bpmn-auto-layout": "npm:bpmn-auto-layout@^2.0.0-alpha.2"
  },
  "tasks": {
    "start": "deno run --allow-net --allow-read --allow-env main.ts",
    "start-instance": "deno run --allow-net --allow-read --allow-env scripts/start-instance.ts",
    "approve": "deno run --allow-net --allow-read --allow-env scripts/approve.ts",
    "job-types": "deno run --allow-net --allow-read --allow-env scripts/job-types.ts"
  }
}
"#;

/// Authoring-time TypeScript config for a code-first project. Types for
/// `@nanobpm/workflow` resolve from `node_modules` after `npm install`.
const WORKFLOW_TSCONFIG_JSON: &str = r#"{
  "compilerOptions": {
    "target": "esnext",
    "module": "nodenext",
    "moduleResolution": "nodenext",
    "allowImportingTsExtensions": true,
    "noEmit": true,
    "strict": true,
    "skipLibCheck": true,
    "lib": ["esnext", "dom"]
  },
  "include": ["main.ts", "workflows/**/*.ts", "scripts/**/*.ts"],
  "exclude": ["node_modules", "dist"]
}
"#;

/// `package.json` for a code-first project: node identity + the real
/// `@nanobpm/workflow` dependency (so `npm install` + node/tsc resolve it).
fn workflow_package_json(name: &str) -> String {
    format!(
        r#"{{
  "name": "{}",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "main": "main.ts",
  "scripts": {{
    "start": "deno task start",
    "start-instance": "deno task start-instance",
    "approve": "deno task approve",
    "job-types": "deno task job-types"
  }},
  "dependencies": {{
    "@nanobpm/workflow": "^0.3.0"
  }},
  "devDependencies": {{
    "@types/node": "^22",
    "bpmn-auto-layout": "^2.0.0-alpha.2"
  }}
}}
"#,
        slugify_app_id(name)
    )
}

/// Example **declarative flow** — the code-first surface (ADR 0044/0045). It
/// demonstrates all three step verbs:
/// - `w.run(name, fn)` — a real, engine-visible BPMN service task this app
///   hosts itself (an ordinary in-process worker — no replay/determinism
///   discipline);
/// - `w.task(name)` — the **agentic seam** (ADR 0046 "agent-as-worker"): a
///   service task with a derived job type serviced by a worker **outside** this
///   program (a coding-agent harness). Its I/O is a typed envelope pair (the
///   `contracts` passed to `defineFlow`); its worker-subscription contract —
///   the derived job type string — is surfaced by `externalJobTypes(flow)`;
/// - `w.signal(name, { correlationKey })` — a durable human-in-the-loop wait (a
///   correlated message catch event).
///
/// A crash mid-flow resumes from the engine journal without re-running completed
/// steps. Jobs are at-least-once, so step handlers must be idempotent.
const WORKFLOW_EXAMPLE_TS: &str = r#"import { defineFlow, envelope, externalJobTypes } from "@nanobpm/workflow";

// A code-first "review a pull request" flow showing all three step verbs:
//
//   fetchDiff      w.run     in-process work this app hosts itself
//   review         w.task    an EXTERNAL step — a coding-agent harness services
//                            the derived job type `pr-review:review`
//   humanApproval  w.signal  a durable human-in-the-loop wait (catch event)
//   merge          w.run     in-process work this app hosts itself
//
// A crash between a side effect and its job completion redelivers the step
// (at-least-once), so keep every step handler idempotent — the in-process
// `w.run` workers AND the external `w.task` harness worker (which can also see
// redeliveries).

// Typed data envelopes (ADR 0045) declare the external `review` step's I/O
// contract IN CODE. They are lifted into the derived BPMN as a `nano:shape` +
// `io.nanobpm.dataEnvelope` property, so the harness — and a future model-first
// eject — sees exactly what to read and return. `env.type` is a phantom type:
// it never exists at runtime.
const contracts = {
  review: {
    in: envelope("PrReviewIn", { prId: "string", files: "integer", additions: "integer" }),
    out: envelope("PrReviewOut", { verdict: "string", notes: "string" }),
  },
};

export const prReview = defineFlow("pr-review", contracts, (w) => {
  w.run("fetchDiff", async (job) => {
    const prId = job.variables.prId;
    if (typeof prId !== "string" || prId.length === 0) {
      throw new Error("pr-review requires a non-empty string `prId` input");
    }
    // Idempotent: reading a diff is a pure read.
    return { files: 3, additions: 42 };
  });

  // The agentic seam (ADR 0046 "agent-as-worker"). `review` is NOT hosted by
  // this app's in-process Worker: it is a service task whose derived job type is
  // `pr-review:review`, serviced by a coding-agent harness running OUTSIDE this
  // program (e.g. hand the diff to an LLM and return its verdict). Point a
  // harness at it — until one is hosted, every instance PARKS here, which is the
  // whole point: the engine durably owns the wait.
  //
  //   c8ctl nano hire            # create a reviewer agent profile (once)
  //   c8ctl nano work <name>     # host it against the job type pr-review:review
  //
  // The engine only routes-to and awaits the agent; the agent's tools and
  // reasoning are its own, opaque to the engine. See the README.
  w.task("review");

  // Durable wait for a human decision, correlated on the instance's `prId`.
  // Resume it with `scripts/approve.ts` (see README) — this is the surface
  // Temporal-style code-first cannot draw: a real, visible catch event.
  w.signal("humanApproval", { correlationKey: "prId" });

  w.run("merge", async (job) => {
    // Idempotent: keyed by prId; a redelivery re-merges the same PR. `verdict`
    // was produced by the external reviewer (see the `review` out envelope).
    return { merged: job.variables.verdict === "approve", approvedBy: job.variables.approvedBy ?? null };
  });
});

// The external job type(s) a harness must service — `["pr-review:review"]`.
// `scripts/job-types.ts` prints this so you can confirm exactly what to
// `c8ctl nano work` against; a mismatch would park every instance forever.
export const externalReviewJobTypes = externalJobTypes(prReview);
"#;

/// Entrypoint: the standalone **worker-host service**. It deploys the
/// workflow(s), hosts a Worker, and runs forever (until Ctrl-C / SIGTERM) —
/// exactly what "just run my application" should mean. Running it in the console
/// / IDE ("Run") executes this same file, so standalone and in-IDE are identical.
/// To kick off an instance, run `scripts/start-instance.ts` (see README).
const WORKFLOW_MAIN_TS: &str = r#"// Code-first durable workflows on Nano (ADR 0044/0045). No diagram, no task-type
// wiring, no correlation plumbing: @nanobpm/workflow derives the executable BPMN
// model, the job types, and hosts a generic Worker.
//
// This is the whole application: it deploys the workflows and hosts their
// workers in-process, then runs forever. Run it standalone (`deno task start`)
// or with the console/IDE "Run" button — same artifact, same entrypoint.
import { WorkflowClient, Worker } from "@nanobpm/workflow";
import { prReview } from "./workflows/pr-review.ts";

const baseUrl = (Deno.env.get("NANOBPMN_BASE_URL") ?? "http://localhost:8080").replace(/\/+$/, "");
const workflows = [prReview];

// 1) Deploy the derived BPMN for each workflow (idempotent — safe to redeploy).
const client = new WorkflowClient({ baseUrl });
for (const wf of workflows) {
  await client.deploy(wf);
  console.log(`deployed ${wf.id}`);
}

// 2) Host the workers in-process. The poll loops reconnect on their own, so the
//    host survives an engine restart.
const worker = new Worker({
  baseUrl,
  workflows,
  onError: (err) => console.error("worker error:", err.message),
});
worker.start();
console.log(`worker host running against ${baseUrl} — press Ctrl-C to stop`);

// 3) Run forever; stop cleanly on Ctrl-C / SIGTERM so in-flight polls drain.
let shuttingDown = false;
const drainAndExit = async () => {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log("\nshutting down…");
  await worker.stop();
  Deno.exit(0);
};
// Deno.addSignalListener expects a synchronous handler (() => void), so wrap
// the async drain logic in a sync closure rather than passing it directly.
const shutdown = (): void => {
  void drainAndExit();
};
for (const sig of ["SIGINT", "SIGTERM"] as const) {
  try {
    Deno.addSignalListener(sig, shutdown);
  } catch {
    // Signal not supported on this OS (e.g. SIGTERM on Windows) — skip it.
  }
}
await new Promise<void>(() => {}); // keep the process alive until a signal fires
"#;

/// Example script that kicks off a single workflow instance against the running
/// app/gateway. Kept OUT of `main.ts` so the app is a pure long-running service:
/// start the host with `deno task start`, then run this to create work.
const WORKFLOW_START_INSTANCE_TS: &str = r#"// Kick off one `pr-review` instance against the running app/gateway.
//
//   deno task start                 # in one shell: the worker-host service
//   deno task start-instance PR-42  # in another: create an instance
import { WorkflowClient } from "@nanobpm/workflow";
import { prReview } from "../workflows/pr-review.ts";

const baseUrl = (Deno.env.get("NANOBPMN_BASE_URL") ?? "http://localhost:8080").replace(/\/+$/, "");
const prId = Deno.args[0] ?? "PR-1234";

const client = new WorkflowClient({ baseUrl });
const { processInstanceKey } = await client.start(prReview, { prId });
console.log(`started ${prReview.id} instance ${processInstanceKey} (prId=${prId})`);
"#;

/// Example script that resumes a parked instance by correlating the
/// `humanApproval` signal — the human-in-the-loop half of the flow. This is the
/// declarative surface's differentiator: a real, engine-visible catch event.
const WORKFLOW_APPROVE_TS: &str = r#"// Approve a parked `pr-review` instance: correlate the `humanApproval` signal on
// its prId so the flow proceeds from the durable wait to `merge`.
//
//   deno task start                 # the worker-host service
//   deno task start-instance PR-42  # create an instance (parks on `review`, then humanApproval)
//   deno task approve PR-42         # resume it past the human-in-the-loop wait
//
// Note: the instance first parks on the external `review` w.task until a harness
// services `pr-review:review`; only then does it reach the humanApproval wait
// this script resumes. See the README's "external-agent seam" section.
import { WorkflowClient } from "@nanobpm/workflow";
import { prReview } from "../workflows/pr-review.ts";

const baseUrl = (Deno.env.get("NANOBPMN_BASE_URL") ?? "http://localhost:8080").replace(/\/+$/, "");
const prId = Deno.args[0] ?? "PR-1234";

const client = new WorkflowClient({ baseUrl });
try {
  await client.signal(prReview, "humanApproval", prId, { approvedBy: "me" });
  console.log(`approved ${prReview.id} (prId=${prId})`);
} catch (err) {
  // The most common cause is signalling before the instance has reached the
  // humanApproval wait: it is still parked on the external `review` w.task, so
  // there is no open `humanApproval` subscription yet (the gateway returns 404).
  console.error(
    `could not approve ${prReview.id} (prId=${prId}): ${err instanceof Error ? err.message : err}\n` +
      "Is the instance still parked on `review`? Host a worker for `pr-review:review` " +
      "(deno task job-types) so it advances to the humanApproval wait, then retry.",
  );
  Deno.exit(1);
}
"#;

/// Example script that prints the flow's **external** job types — the ones a
/// coding-agent harness (`c8ctl nano hire`/`work`) must service. Kept as a
/// script so the number the README tells you to `hire` against is derived from
/// the code, never hand-copied (a mismatch would silently park instances).
const WORKFLOW_JOB_TYPES_TS: &str = r#"// Print the EXTERNAL job types this app expects a harness to service.
//
//   deno task job-types            # -> pr-review:review
//
// Point a coding-agent harness at exactly these (see README): until one is
// hosted, instances park on the `review` step. No gateway needed — this only
// inspects the derived model.
import { externalJobTypes } from "@nanobpm/workflow";
import { prReview } from "../workflows/pr-review.ts";

const types = externalJobTypes(prReview);
if (types.length === 0) {
  console.log("no external (w.task) steps — every step is hosted in-process");
} else {
  // One bare job type per line, so `deno task job-types` output is exactly what
  // the README tells you to hire against (copy/paste straight into a harness).
  for (const t of types) console.log(t);
}
"#;

/// README for a code-first project.
fn workflow_readme(name: &str) -> String {
    format!(
        r#"# {name}

A **code-first durable workflow** project (ADR 0044/0045). You write ordinary
async code; [`@nanobpm/workflow`](https://www.npmjs.com/package/@nanobpm/workflow)
derives the executable BPMN model, the job types and the wiring, and hosts a
generic worker against a running Nano gateway.

This project is a **standalone runnable application**: `main.ts` deploys the
workflows and hosts their workers in-process, then runs forever. It's the same
artifact whether you run it from a shell or with the console/IDE **Run** button.

## Run

```sh
deno task start          # or: npm install && npm start
```

That starts the long-running worker-host service (Ctrl-C to stop). Point it at a
non-default gateway with `NANOBPMN_BASE_URL`.

To drive an instance through the flow, in another shell (the host must be
running):

```sh
deno task start-instance PR-42     # kicks off one pr-review instance
```

The instance first parks on the **`review`** step — an external `w.task` (see
below) — and stays there until an external worker completes the `pr-review:review`
job. Only then does it advance to the human-in-the-loop wait, which you resume
with:

```sh
deno task approve PR-42            # resume it past the human-in-the-loop wait
```

> If nothing seems to happen after `start-instance`, that's expected: the
> instance is durably parked on `review` waiting for an external agent. See
> **The external-agent seam** below to service it.

## The external-agent seam (`w.task`)

The `review` step is a **`w.task`**: an external service task this app does
**not** host. It is the agentic seam (ADR 0046 "agent-as-worker") — the engine
routes to and awaits a coding-agent harness, and the agent's tools and reasoning
are its own, opaque to the engine. The step's derived job type is:

```
pr-review:review
```

Confirm it straight from the code (never hand-copy it):

```sh
deno task job-types      # -> pr-review:review
```

> **This starter does not run end-to-end on its own — by design.** A fresh
> instance runs `fetchDiff`, then **parks on `review`** until a worker services
> `pr-review:review`. The park *is* the lesson: the engine durably owns the wait
> (nothing is lost across a restart), exactly as it does for the `humanApproval`
> signal. Journey 0a's success is "a worker host is up", not "an instance
> completed".

Host a coding-agent harness for that job type with `c8ctl nano hire` / `work`:

```sh
c8ctl nano hire          # create a reviewer agent profile (once, interactive)
c8ctl nano work <name>   # host it — it services the job type pr-review:review
```

Once a worker completes the `review` job (returning the `PrReviewOut` envelope —
`verdict` + `notes`), the instance advances to the `humanApproval` wait, and
`deno task approve` carries it to `merge`.

## Author

- `workflows/pr-review.ts` — an example **declarative flow** demonstrating all
  three step verbs. Add more flows with `defineFlow(id, contracts, (w) => {{ ... }})`
  and list them in `main.ts`.
- `w.run(name, fn)` becomes a real, engine-visible BPMN service task **hosted
  in-process** by this app's worker; a crash mid-flow resumes from the engine
  journal without re-running completed steps. Jobs are **at-least-once**, so keep
  handlers idempotent.
- `w.task(name)` declares a step served by a worker **outside this program** — a
  service task whose derived job type (`pr-review:review` here) a coding-agent
  harness polls. The in-process `Worker` does **not** host it; list the contract
  with `externalJobTypes(flow)` (see `scripts/job-types.ts`). Typed data
  envelopes on the step (`PrReviewIn`/`PrReviewOut`) declare its I/O in code and
  are lifted into the derived BPMN.
- `w.signal(name, {{ correlationKey }})` is a durable human-in-the-loop wait — a
  correlated message catch event. `scripts/approve.ts` shows how a client
  resumes it. This is what a diagram-less, Temporal-style code-first surface
  cannot give you: a real, visible catch event.
- `scripts/start-instance.ts` starts an instance — keep the worker host
  (`main.ts`) a pure long-running service.

## What gets derived

`WorkflowClient.deploy(flow)` deploys the BPMN that `@nanobpm/workflow` emits from
your code; the `Worker` routes the derived job types (`{{id}}:step`) back to your
`run` handlers. Inspect the derived model with `toBpmn(flow)`.

> **Advanced:** an experimental imperative (Temporal-style replay) surface
> (`defineWorkflow` + `ctx.run`) also exists for arbitrary control flow, but its
> steps are not engine-visible and it requires determinism discipline. Prefer
> `defineFlow`.
"#,
        name = name
    )
}

// ---------------------------------------------------------------------------
// "Throughput Explorer" demo template — a 30-second ceiling finder
// ---------------------------------------------------------------------------

/// A minimal one-task process: start → single service task ("tick") → end. The
/// worker auto-completes, so each created instance runs end-to-end through the
/// engine: this measures create + worker-complete throughput.
const DEMO_PROCESS_BPMN: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:zeebe="http://camunda.org/schema/zeebe/1.0" id="defs-throughput-demo" targetNamespace="http://nanobpm">
  <bpmn:process id="throughput-demo" isExecutable="true">
    <bpmn:startEvent id="start">
      <bpmn:outgoing>f1</bpmn:outgoing>
    </bpmn:startEvent>
    <bpmn:sequenceFlow id="f1" sourceRef="start" targetRef="task" />
    <bpmn:serviceTask id="task" name="Tick">
      <bpmn:extensionElements>
        <zeebe:taskDefinition type="tick" />
      </bpmn:extensionElements>
      <bpmn:incoming>f1</bpmn:incoming>
      <bpmn:outgoing>f2</bpmn:outgoing>
    </bpmn:serviceTask>
    <bpmn:sequenceFlow id="f2" sourceRef="task" targetRef="end" />
    <bpmn:endEvent id="end">
      <bpmn:incoming>f2</bpmn:incoming>
    </bpmn:endEvent>
  </bpmn:process>
  <bpmndi:BPMNDiagram id="diagram">
    <bpmndi:BPMNPlane id="plane" bpmnElement="throughput-demo">
      <bpmndi:BPMNShape id="start_di" bpmnElement="start">
        <dc:Bounds x="160" y="100" width="36" height="36" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="task_di" bpmnElement="task">
        <dc:Bounds x="260" y="78" width="100" height="80" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="end_di" bpmnElement="end">
        <dc:Bounds x="430" y="100" width="36" height="36" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNEdge id="f1_di" bpmnElement="f1">
        <di:waypoint x="196" y="118" />
        <di:waypoint x="260" y="118" />
      </bpmndi:BPMNEdge>
      <bpmndi:BPMNEdge id="f2_di" bpmnElement="f2">
        <di:waypoint x="360" y="118" />
        <di:waypoint x="430" y="118" />
      </bpmndi:BPMNEdge>
    </bpmndi:BPMNPlane>
  </bpmndi:BPMNDiagram>
</bpmn:definitions>
"#;

/// The single worker: drains "tick" jobs as fast as it can, fire-and-forget.
const DEMO_WORKER_TS: &str = r#"import { defineWorker } from "@nanobpm/worker";

// Drains "tick" jobs as fast as the engine emits them. High parallelism + an
// empty handler keep the worker off the critical path so the engine sets the
// ceiling, not the worker.
defineWorker({
  type: "tick",
  maxParallelJobs: 200,
  async handle() {
    return {};
  },
});
"#;

/// The explorer entrypoint: deploy, start the worker, then ramp instance
/// creation every 2s for 30s and report the peak sustained rate.
const DEMO_MAIN_TS: &str = r#"// Throughput (REST) — finds the ceiling using the plain HTTP API.
//
// For 30 seconds it fires-and-forgets process-instance creates over REST
// (POST /v2/process-instances, no awaiting completion) with a pool that ramps
// every 2 seconds. The single "tick" worker drains the jobs. A/B this against
// the "Throughput (falcon)" demo, which runs identical logic through
// @nanobpm/nano-sdk on the Falcon protocol.
import { BASE_URL, deployAllResources, startWorkers } from "@lib/nano.ts";

const PROCESS_ID = "throughput-demo";
const DURATION_MS = 30_000;
const RAMP_EVERY_MS = 2_000;
const RAMP_STEP = 32; // +32 concurrent creators every 2s
const DRAIN_MAX_MS = 30_000; // give the worker up to 30s to finish the backlog

async function residentMb(): Promise<number> {
  try {
    const r = await fetch(`${BASE_URL}/v2/system/memory`);
    const j = await r.json();
    return j.residentBytes ? j.residentBytes / 1_048_576 : 0;
  } catch { return 0; }
}

await deployAllResources();
await startWorkers({ include: ["tick"] });

let created = 0;
let running = true;
let concurrency = 0;

async function creator(): Promise<void> {
  const body = JSON.stringify({ processDefinitionId: PROCESS_ID as unknown as never, awaitCompletion: false });
  const headers = { "content-type": "application/json" };
  while (running) {
    try {
      const r = await fetch(`${BASE_URL}/v2/process-instances`, { method: "POST", body, headers });
      await r.body?.cancel(); // free the connection promptly
      if (r.ok) created++;
    } catch { /* keep pushing */ }
  }
}

console.log("ramping process-instance creation for 30s…\n");
const t0 = performance.now();
let lastCreated = 0;
let peak = 0;
let peakMem = 0;

const tick = setInterval(async () => {
  const total = created;
  const rate = total - lastCreated;
  lastCreated = total;
  if (rate > peak) peak = rate;
  const mem = await residentMb();
  if (mem > peakMem) peakMem = mem;
  console.log(`t+${Math.round((performance.now() - t0) / 1000)}s  conc=${concurrency}  ${rate}/s  (total ${total}, mem ${mem.toFixed(0)}MB)`);
}, 1000);

const ramp = setInterval(() => {
  for (let i = 0; i < RAMP_STEP; i++) creator();
  concurrency += RAMP_STEP;
}, RAMP_EVERY_MS);

for (let i = 0; i < RAMP_STEP; i++) creator();
concurrency = RAMP_STEP;

setTimeout(async () => {
  running = false; // stop creating
  clearInterval(ramp);
  console.log(`\n${created} created. draining the backlog (worker finishing jobs)…`);
  // Graceful drain: stop creating and wait until the engine reports no jobs
  // pending, or DRAIN_MAX_MS elapses, so we don't leave instances parked.
  const drainStart = performance.now();
  let prev = -1;
  while (performance.now() - drainStart < DRAIN_MAX_MS) {
    await new Promise((r) => setTimeout(r, 1000));
    let pending = 0;
    try {
      const r = await fetch(`${BASE_URL}/v2/jobs/search`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ filter: { type: "tick", state: "CREATED" }, page: { limit: 1 } }),
      });
      const j = await r.json();
      pending = j?.page?.totalItems ?? 0;
    } catch { break; }
    const mem = await residentMb();
    if (mem > peakMem) peakMem = mem;
    console.log(`  pending jobs: ${pending}`);
    if (pending === 0 || pending === prev) break; // done, or stuck — stop waiting
    prev = pending;
  }
  clearInterval(tick);
  console.log(`\n=== peak ${peak} instances/sec (single-task, fire-and-forget) ===`);
  console.log(`=== ${created} instances created in 30s, ~${Math.round(created / 30)}/s average ===`);
  console.log(`=== peak engine memory ${peakMem.toFixed(0)}MB ===`);
  Deno.exit(0);
}, DURATION_MS);
"#;

fn demo_readme() -> String {
    "# Throughput Explorer\n\n\
A 30-second benchmark that shows how fast Nano runs out of the box. It \
fire-and-forgets `throughput-demo` instances (a single auto-completed `tick` \
task) from a creator pool that ramps every 2 seconds, while one worker drains \
the jobs. Each second it prints the achieved **creates/sec** and the engine's \
**resident memory**; at 30s it stops creating, drains the backlog (so no \
instances are left parked), then reports the peak instances/sec and peak memory.\n\n\
## Run it in the IDE\n\n\
1. Make sure the engine is up (the console you're reading this in is the engine).\n\
2. Open this project and press **Run**. Watch the log console fill with per-second \
rates; the final lines report the peak. It runs ~30s then drains and stops on its \
own. Press **Stop** anytime to end early.\n\n\
## A/B: falcon vs REST\n\n\
Pair this with **Throughput (falcon)** (same benchmark via \
`@nanobpm/nano-sdk`). On a clean engine (30s ramp, fire-and-forget):\n\n\
| Metric | REST (this demo) | Falcon |\n\
|---|---|---|\n\
| Peak instances/sec | **8,353** | 4,393 |\n\
| Avg instances/sec | 7,593 | 2,753 |\n\
| Created in 30s | 227,780 | 82,591 |\n\
| Peak engine memory | 233 MB | **58 MB** |\n\n\
REST wins raw throughput (pooled HTTP connections parallelise well); the \
Falcon protocol uses ~4x less engine memory. Run each on a fresh engine \
(`c8ctl nano stop --purge` between runs) for a fair comparison.\n\n\
> **Note:** in JavaScript/Deno there is no falcon *throughput* win — \
even across two processes (separate producer + worker) the SDK awaits one \
create at a time over a single socket (~2–3k/s) while pooled REST fans out \
across many connections (~20k/s). The stream's only JS benefit is ~4x lower \
engine memory. Its throughput edge needs a pipelining native producer \
(e.g. Rust), where it beats REST ~32k vs ~20k.\n\n\
## Reclaim disk after the test\n\n\
The benchmark creates ~1M instances; their journal/data can be large. When you're \
done, free the disk with:\n\n\
```sh\nc8ctl nano stop --purge\n```\n\n\
or, equivalently:\n\n\
```sh\nc8ctl nano stop && c8ctl nano clean\n```\n"
        .into()
}

/// Stream variant deno.json: pulls the Nano SDK (drop-in C8 client) which
/// auto-upgrades to the Falcon protocol against a Nano server.
const DEMO_STREAM_DENO_JSON: &str = r#"{
  "imports": {
    "@nanobpm/nano-sdk": "npm:@nanobpm/nano-sdk@^1",
    "@nanobpm/llm": "./{GEN}/llm-worker.ts",
    "@lib/": "./lib/"
  },
  "tasks": {
    "start": "deno run --allow-net --allow-read --allow-write --allow-env --allow-sys main.ts"
  }
}
"#;

/// The falcon entrypoint: identical benchmark to the REST demo, but
/// creation + the worker run through @nanobpm/nano-sdk, which upgrades to the
/// falcon protocol on Nano. A/B it against the REST demo.
const DEMO_STREAM_MAIN_TS: &str = r#"// Throughput (falcon) — same benchmark, run through @nanobpm/nano-sdk.
//
// Identical to the "Throughput (REST)" demo, except instance creation and the
// "tick" worker go through the Nano SDK, which auto-upgrades to the command
// stream when it detects a Nano server. Compare the peak/sec against REST.
import { createCamundaClient } from "@nanobpm/nano-sdk";
import { deployAllResources } from "@lib/nano.ts";

const BASE_URL = (Deno.env.get("NANOBPMN_BASE_URL") ?? "http://localhost:8080").replace(/\/+$/, "");
const PROCESS_ID = "throughput-demo";
const DURATION_MS = 30_000;
const RAMP_EVERY_MS = 2_000;
const RAMP_STEP = 32;

const client = createCamundaClient({
  config: { CAMUNDA_AUTH_STRATEGY: "NONE", CAMUNDA_REST_ADDRESS: BASE_URL, CAMUNDA_TRANSPORT: "auto" },
});

async function residentMb(): Promise<number> {
  try {
    const r = await fetch(`${BASE_URL}/v2/system/memory`);
    const j = await r.json();
    return j.residentBytes ? j.residentBytes / 1_048_576 : 0;
  } catch { return 0; }
}

await deployAllResources();
client.createJobWorker({ jobType: "tick", maxParallelJobs: 200, jobHandler: (job: any) => job.complete({}) });

let created = 0;
let running = true;
let concurrency = 0;

async function creator(): Promise<void> {
  while (running) {
    try {
      await client.createProcessInstance({ processDefinitionId: PROCESS_ID as unknown as never, awaitCompletion: false });
      created++;
    } catch { /* keep pushing */ }
  }
}

console.log("ramping process-instance creation for 30s (Falcon protocol)…\n");
const t0 = performance.now();
let lastCreated = 0;
let peak = 0;
let peakMem = 0;

const tick = setInterval(async () => {
  const total = created;
  const rate = total - lastCreated;
  lastCreated = total;
  if (rate > peak) peak = rate;
  const mem = await residentMb();
  if (mem > peakMem) peakMem = mem;
  console.log(`t+${Math.round((performance.now() - t0) / 1000)}s  conc=${concurrency}  ${rate}/s  (total ${total}, mem ${mem.toFixed(0)}MB)`);
}, 1000);

const ramp = setInterval(() => {
  for (let i = 0; i < RAMP_STEP; i++) creator();
  concurrency += RAMP_STEP;
}, RAMP_EVERY_MS);

for (let i = 0; i < RAMP_STEP; i++) creator();
concurrency = RAMP_STEP;

setTimeout(() => {
  running = false;
  clearInterval(ramp);
  clearInterval(tick);
  console.log(`\n=== peak ${peak} instances/sec (Falcon protocol, fire-and-forget) ===`);
  console.log(`=== ${created} instances created in 30s, ~${Math.round(created / 30)}/s average ===`);
  console.log(`=== peak engine memory ${peakMem.toFixed(0)}MB ===`);
  client.stopAllWorkers?.();
  Deno.exit(0);
}, DURATION_MS);
"#;

fn demo_stream_readme() -> String {
    "# Throughput (falcon)\n\n\
A/B partner to **Throughput (REST)**. Identical 30-second ramp benchmark, but \
instance creation and the `tick` worker run through `@nanobpm/nano-sdk` — a \
drop-in Camunda 8 client that upgrades to Nano's falcon protocol. \
Compare its peak instances/sec against the REST demo to see the wire-protocol \
difference on the same engine.\n\n\
## Run it in the IDE\n\n\
1. Make sure the engine is up (this console is the engine).\n\
2. Open this project and press **Run**; compare the peak with the REST demo.\n\n\
## A/B: falcon vs REST\n\n\
On a clean engine (30s ramp, fire-and-forget):\n\n\
| Metric | Falcon (this demo) | REST |\n\
|---|---|---|\n\
| Peak instances/sec | 4,393 | **8,353** |\n\
| Avg instances/sec | 2,753 | 7,593 |\n\
| Created in 30s | 82,591 | 227,780 |\n\
| Peak engine memory | **58 MB** | 233 MB |\n\n\
The Falcon protocol trades raw throughput for ~4x lower engine memory; REST \
parallelises better over pooled HTTP connections. Run each on a fresh engine \
(`c8ctl nano stop --purge` between runs) for a fair comparison.\n\n\
> **Note:** in JavaScript/Deno the stream does *not* win on throughput — even \
splitting producer and worker into two processes, the SDK awaits one create \
at a time over a single socket (~2–3k/s) vs pooled REST (~20k/s). Pick the \
stream here for low engine memory, not speed; its throughput edge needs a \
pipelining native producer (Rust beats REST ~32k vs ~20k).\n\n\
## Reclaim disk after the test\n\n\
```sh\nc8ctl nano stop --purge\n```\n"
        .into()
}

