    #[test]
    fn urban_template_scaffolds_app_manifest_and_dirs() {
        let _g = lock();
        let root = temp_root();
        let cfg = create_project("Home_Heating", "", "urban-starter").expect("create");
        assert_eq!(cfg.app, "urban");
        assert_eq!(cfg.template.as_deref(), Some("urban-starter"));
        let dir = root.join("Home_Heating");
        // Manifest is the source of truth; model + data + public dirs are scaffolded.
        let manifest_path = dir.join("nano.app.json");
        assert!(manifest_path.is_file(), "nano.app.json must exist");
        assert!(dir.join("resources/processes").is_dir());
        assert!(dir.join("resources/decisions").is_dir());
        assert!(dir.join("resources/forms").is_dir());
        assert!(dir.join("db/migrations").is_dir());
        // The Urban entrypoint serves its composed pages via `@nanobpm/app`, so
        // the scaffold no longer ships a static `public/index.html` (which used to
        // reference a `/api/app` endpoint that no longer exists).
        assert!(
            !dir.join("public/index.html").exists(),
            "no vestigial public/index.html"
        );
        assert!(dir.join("main.ts").is_file());
        // ADR 0042: the app's composed screen is scaffolded and the Urban
        // entrypoint serves it via the generic `@nanobpm/app` runtime — no
        // hand-written frontend or JSON API.
        assert!(
            dir.join("pages/home.page.json").is_file(),
            "pages/home.page.json must be scaffolded"
        );
        let page: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(dir.join("pages/home.page.json")).unwrap(),
        )
        .expect("home.page.json parses");
        assert_eq!(page["schemaVersion"], "1.0");
        assert_eq!(
            page["nodes"][2]["props"]["action"]["process"], "Home_Heating-process",
            "the starter actionForm binds to the scaffold's process"
        );
        let main_ts = std::fs::read_to_string(dir.join("main.ts")).unwrap();
        assert!(
            main_ts.contains("servePages("),
            "the Urban entrypoint serves its composed pages via @nanobpm/app"
        );
        let manifest: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&manifest_path).unwrap())
                .expect("manifest parses");
        assert_eq!(manifest["schemaVersion"], 1);
        assert_eq!(manifest["id"], "home-heating");
        assert_eq!(manifest["name"], "Home_Heating");
        assert_eq!(manifest["data"]["sources"]["app"]["driver"], "sqlite");
        assert_eq!(manifest["surfaces"]["taskInbox"]["enabled"], true);
        // The scaffold ships a complete LLM-worker example matching the
        // classify-llm component: workers[].llm → llm.classifier (ADR 0022 §E).
        assert_eq!(manifest["workers"][0]["taskType"], "classify");
        assert_eq!(manifest["workers"][0]["llm"], "classifier");
        assert_eq!(manifest["llm"]["classifier"]["provider"], "env");
        assert!(manifest["llm"]["classifier"]["model"].is_string());
        // ADR 0024 phase-1 core: the embedded datasource SDK is materialised and
        // its `@nanobpm/data` alias is wired into the project + worker import maps
        // so `openDataSource()` / `ctx.data()` resolve at runtime.
        assert!(
            dir.join("nano-generated/data-sdk.ts").is_file(),
            "nano-generated/data-sdk.ts must be materialised"
        );
        let deno_json: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(dir.join("deno.json")).unwrap())
                .expect("deno.json parses");
        assert_eq!(
            deno_json["imports"]["@nanobpm/data"], "./nano-generated/data-sdk.ts",
            "@nanobpm/data must be import-mapped"
        );
        // ADR 0029 §6: the typed data-object accessor is seeded and aliased so
        // `import { openDomain } from "@nanobpm/domain"` resolves from scaffold.
        assert!(
            dir.join("nano-generated/domain.ts").is_file(),
            "nano-generated/domain.ts must be seeded"
        );
        assert_eq!(
            deno_json["imports"]["@nanobpm/domain"], "./nano-generated/domain.ts",
            "@nanobpm/domain must be import-mapped"
        );
        // ADR 0033 §3: the typed `defineWorker` wrapper is materialised and
        // `@nanobpm/worker` resolves to it (its IO map `worker-io.d.ts` is seeded).
        assert!(
            dir.join("nano-generated/workers.ts").is_file(),
            "nano-generated/workers.ts must be materialised"
        );
        assert!(
            dir.join("nano-generated/worker-io.d.ts").is_file(),
            "nano-generated/worker-io.d.ts must be seeded"
        );
        assert_eq!(
            deno_json["imports"]["@nanobpm/worker"], "./nano-generated/workers.ts",
            "@nanobpm/worker must resolve to the typed wrapper"
        );
        // ADR 0022 §E role 1: the LLM-as-worker runtime is materialised and
        // aliased, and the Urban entrypoint boots it (workers[].llm → llm.<id>).
        assert!(
            dir.join("nano-generated/llm-worker.ts").is_file(),
            "nano-generated/llm-worker.ts must be materialised"
        );
        assert_eq!(
            deno_json["imports"]["@nanobpm/llm"], "./nano-generated/llm-worker.ts",
            "@nanobpm/llm must be import-mapped"
        );
        // Node-first standard-tooling parity: the scaffold emits a `tsconfig.json`
        // (so VS Code / `tsc` resolve `@nanobpm/*` natively via `paths`, mirroring
        // the `deno.json` import map) and a `package.json` (npm identity + a place
        // for `npm install` deps, with `@types/node` for `node:*` builtins). The
        // `@nanobpm/*` alias stays in `deno.json`/`tsconfig.json` — `package.json`
        // cannot express it (`imports` keys must be `#`-prefixed).
        let tsconfig: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(dir.join("tsconfig.json")).unwrap())
                .expect("tsconfig.json parses");
        assert_eq!(
            tsconfig["compilerOptions"]["paths"]["@nanobpm/worker"][0],
            "./nano-generated/workers.ts",
            "tsconfig must map @nanobpm/worker to the typed wrapper"
        );
        assert_eq!(
            tsconfig["compilerOptions"]["paths"]["@nanobpm/domain"][0],
            "./nano-generated/domain.ts"
        );
        let package_json: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(dir.join("package.json")).unwrap())
                .expect("package.json parses");
        assert_eq!(package_json["type"], "module");
        assert!(
            package_json["devDependencies"]["@types/node"].is_string(),
            "package.json must pull @types/node for node: builtins"
        );
        assert!(
            package_json["imports"].is_null(),
            "the @nanobpm/* alias must not live in package.json (imports is #-prefixed only)"
        );
        // The reified type files carry distinct stems from their runtime accessors
        // (`domain.ts`/`workers.ts`), so a project `tsconfig.json` `paths` map does
        // not trip TypeScript's `.d.ts`-pairing circular-import error.
        assert!(
            dir.join("nano-generated/worker-io.d.ts").is_file(),
            "worker IO map must use the distinct-stem name worker-io.d.ts"
        );
        assert!(
            !dir.join("nano-generated/workers.d.ts").exists(),
            "the stem-colliding workers.d.ts must not be emitted"
        );
        let urban_main = std::fs::read_to_string(dir.join("main.ts")).unwrap();
        assert!(
            urban_main.contains("startLlmWorkers()"),
            "Urban entrypoint must boot llm workers"
        );
        // Components (element templates) seed the BPMN palette (ADR 0033
        // increment 2): the modeler loads them from the project's `components/`
        // dir, so a fresh Urban App ships with a valid, parseable component set.
        let comp_path = dir.join("components/read-thermostat.json");
        assert!(
            comp_path.is_file(),
            "components/read-thermostat.json must exist"
        );
        assert!(dir.join("components/classify-llm.json").is_file());
        let comp: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&comp_path).unwrap())
                .expect("component template parses");
        assert_eq!(comp["id"], "io.nanobpm.urban.read-thermostat");
        assert_eq!(comp["appliesTo"][0], "bpmn:Task");
    }

    #[test]
    fn urban_template_exposes_runtime_option_only() {
        // The urban-starter template declares the Node/Deno runtime toggle via
        // `options`; every other builtin declares none. The wire projection
        // carries the option id, its choices, and the Deno choice's `requires`
        // capability so the console can gate it on `denoAvailable`.
        let templates = project_templates();
        let urban = templates
            .iter()
            .find(|t| t["id"] == "urban-starter")
            .expect("urban-starter template present");
        let options = urban["options"].as_array().expect("options array");
        assert_eq!(options.len(), 1, "urban-starter has one option");
        let runtime = &options[0];
        assert_eq!(runtime["id"], "runtime");
        assert_eq!(runtime["default"], "node");
        let choices = runtime["choices"].as_array().expect("choices array");
        let node = choices.iter().find(|c| c["value"] == "node").unwrap();
        assert!(
            node.get("requires").is_none(),
            "Node is always available (no `requires`)"
        );
        let deno = choices.iter().find(|c| c["value"] == "deno").unwrap();
        assert_eq!(deno["requires"], "deno");
        // Urban apps flag their reliance on the @nanobpm/urban toolkit so the
        // picker can surface the install hint.
        assert_eq!(urban["needsUrban"], true);

        // A non-Urban builtin declares no options and does not need the toolkit.
        let starter = templates
            .iter()
            .find(|t| t["id"] == "gui-starter")
            .expect("gui-starter present");
        assert!(
            starter["options"].as_array().unwrap().is_empty(),
            "gui-starter declares no options"
        );
        assert_eq!(starter["needsUrban"], false);
    }

    #[test]
    fn create_project_with_options_records_runtime_choice() {
        let _g = lock();
        let _root = temp_root();
        let mut opts = std::collections::HashMap::new();
        opts.insert("runtime".to_string(), "deno".to_string());
        let cfg = create_project_with_options("runtime_demo", "", "urban-starter", &opts)
            .expect("create");
        assert_eq!(
            cfg.runtime.as_deref(),
            Some("deno"),
            "the chosen runtime is recorded on the project config"
        );
    }

    #[test]
    fn workflow_template_scaffolds_a_lean_code_first_project() {
        let _g = lock();
        let root = temp_root();
        let cfg = create_project("pr_bot", "", "workflow-starter").expect("create");
        // Recorded as its own template; a Deno console app (the run supervisor
        // drives it as `deno task start`).
        assert_eq!(cfg.template.as_deref(), Some("workflow-starter"));
        assert_eq!(cfg.lang, "deno");
        assert_eq!(cfg.app, "console");
        assert_eq!(cfg.main, "main.ts");
        let dir = root.join("pr_bot");
        // The lean code-first tree: the worker-host entrypoint, an example
        // workflow, the instance-starter script, and the manifests — nothing else.
        assert!(dir.join("main.ts").is_file());
        assert!(dir.join("workflows/pr-review.ts").is_file());
        assert!(dir.join("scripts/start-instance.ts").is_file());
        assert!(dir.join("scripts/approve.ts").is_file());
        assert!(dir.join("scripts/job-types.ts").is_file());
        assert!(dir.join("README.md").is_file());
        // Crucially: NONE of the model-first machinery leaks in — the model is
        // derived from the code, so there is no authored BPMN and no
        // `nano-generated/` tree (ADR 0045).
        assert!(
            !dir.join("nano-generated").exists(),
            "code-first project must not carry the model-first nano-generated/ tree"
        );
        assert!(
            !dir.join("resources").exists(),
            "code-first project must not carry authored resources/ (model is derived)"
        );
        // The import map + package.json depend on the real published SDK, not a
        // generated-file alias.
        let deno_json: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(dir.join("deno.json")).unwrap())
                .expect("deno.json parses");
        assert!(
            deno_json["imports"]["@nanobpm/workflow"]
                .as_str()
                .unwrap_or_default()
                .starts_with("npm:@nanobpm/workflow"),
            "@nanobpm/workflow must resolve to the published npm package"
        );
        let package_json: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(dir.join("package.json")).unwrap())
                .expect("package.json parses");
        assert!(
            package_json["dependencies"]["@nanobpm/workflow"].is_string(),
            "package.json must depend on @nanobpm/workflow"
        );
        // The example uses the declarative surface (THE code-first way): a
        // step list with a human-in-the-loop signal, NOT the imperative replay
        // surface. It must not carry the imperative `ctx.run`/defineWorkflow.
        let example = std::fs::read_to_string(dir.join("workflows/pr-review.ts")).unwrap();
        assert!(example.contains("defineFlow"));
        assert!(example.contains("w.run("));
        assert!(example.contains("w.signal("));
        // The agentic seam (ADR 0046): the `review` step must be an EXTERNAL
        // `w.task`, not an in-process `w.run` — that seam is the whole point of
        // journey 0a step 3. Its typed envelope + the derived job type the
        // README tells users to `hire` against must both be present, and must
        // agree (a mismatch silently parks instances forever — journey 0b).
        assert!(
            example.contains("w.task(\"review\")"),
            "the `review` step must be an external w.task (the agentic seam)"
        );
        assert!(example.contains("envelope(\"PrReviewIn\""));
        assert!(example.contains("envelope(\"PrReviewOut\""));
        assert!(example.contains("externalJobTypes"));
        let readme = std::fs::read_to_string(dir.join("README.md")).unwrap();
        assert!(
            readme.contains("pr-review:review"),
            "README must name the exact derived external job type"
        );
        assert!(
            readme.contains("c8ctl nano hire") && readme.contains("c8ctl nano work"),
            "README must give the hire + work invocation for the external seam"
        );
        let job_types = std::fs::read_to_string(dir.join("scripts/job-types.ts")).unwrap();
        assert!(job_types.contains("externalJobTypes(prReview)"));
        // The README instructs `deno task job-types`, so the package.json script
        // parity must exist or the `npm run job-types` alternative silently breaks
        // (the deno.json task itself is asserted below alongside the other tasks).
        let package_json = std::fs::read_to_string(dir.join("package.json")).unwrap();
        assert!(
            package_json.contains("\"job-types\""),
            "package.json scripts must keep parity with the deno.json job-types task"
        );
        assert!(
            !example.contains("defineWorkflow"),
            "the scaffold must lead with the declarative surface, not imperative replay"
        );
        // main.ts is a durable worker-host SERVICE: it hosts a worker and never
        // self-exits. Starting an instance lives in the script, not the host, so
        // "just run the app" means a long-running service (not a one-shot demo).
        let main_ts = std::fs::read_to_string(dir.join("main.ts")).unwrap();
        assert!(main_ts.contains("worker.start()"));
        assert!(
            !main_ts.contains("client.start("),
            "the worker host must not start an instance itself (that lives in scripts/start-instance.ts)"
        );
        let starter = std::fs::read_to_string(dir.join("scripts/start-instance.ts")).unwrap();
        assert!(
            starter.contains("client.start("),
            "the instance-starter script should start an instance"
        );
        let approve = std::fs::read_to_string(dir.join("scripts/approve.ts")).unwrap();
        assert!(
            approve.contains("client.signal("),
            "the approve script should correlate the human-in-the-loop signal"
        );
        // All Deno tasks are defined (incl. the job-types task the README advertises).
        assert!(deno_json["tasks"]["start"].is_string());
        assert!(deno_json["tasks"]["start-instance"].is_string());
        assert!(deno_json["tasks"]["approve"].is_string());
        assert!(deno_json["tasks"]["job-types"].is_string());
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)] // serialises on the shared PROJECTS_DIR env
    async fn derive_models_degrades_gracefully_without_panicking() {
        let _g = lock();
        let _root = temp_root();
        // An unknown project name / missing dir -> NOT FOUND-style error, no panic.
        let err = derive_models("does_not_exist").await.unwrap_err();
        assert!(
            err.contains("no such") || err.contains("invalid project"),
            "missing project should surface a not-found error, got: {err}"
        );

        // A real project WITHOUT a workflows/ dir (not code-first) -> a clear
        // "not a code-first workflow project" error rather than spawning Deno.
        create_project("plain_app", "", "starter").expect("create");
        let err = derive_models("plain_app").await.unwrap_err();
        assert!(
            err.contains("not a code-first"),
            "a non-workflow project should be rejected before spawning Deno, got: {err}"
        );
    }

    #[test]
    fn slugify_app_id_matches_manifest_pattern() {
        assert_eq!(slugify_app_id("Home Heating"), "home-heating");
        assert_eq!(slugify_app_id("  My   App!! "), "my-app");
        assert_eq!(slugify_app_id("already-good"), "already-good");
        assert_eq!(slugify_app_id("!!!"), "app");
        assert_eq!(slugify_app_id("v2 Beta"), "v2-beta");
    }

    #[test]
    fn project_slug_keeps_safe_names_and_slugs_the_rest() {
        // A name that is already directory-safe is used verbatim — casing,
        // dots and underscores preserved (zero behaviour change).
        assert_eq!(project_slug("MyApp").as_deref(), Some("MyApp"));
        assert_eq!(
            project_slug("order_2.final").as_deref(),
            Some("order_2.final")
        );
        // Display names with spaces (or other unsafe chars) get hyphen-slugged.
        assert_eq!(
            project_slug("Home Heating").as_deref(),
            Some("home-heating")
        );
        assert_eq!(project_slug("  My   App!! ").as_deref(), Some("my-app"));
        assert_eq!(project_slug("v2 Beta").as_deref(), Some("v2-beta"));
        // Nothing slug-worthy => invalid.
        assert_eq!(project_slug("!!!"), None);
        assert_eq!(project_slug(""), None);
    }

    #[test]
    fn create_project_slugs_a_spaced_name_and_keeps_the_display_name() {
        let _g = lock();
        let root = temp_root();
        let cfg = create_project("Home Heating", "warm floors", "starter").expect("create");
        assert_eq!(cfg.name, "home-heating");
        assert_eq!(cfg.display_name.as_deref(), Some("Home Heating"));
        // Files live under the slug; scaffolds (BPMN filename etc.) use it too.
        let dir = root.join("home-heating");
        assert!(dir.join("nanobpm.project.json").is_file());
        assert!(dir.join("resources/processes/home-heating.bpmn").is_file());
        // The slug is taken now — the same display name collides.
        let err = create_project("home heating", "", "starter")
            .err()
            .expect("colliding slug should be rejected");
        assert!(err.contains("already exists"), "got: {err}");
        // The summary surfaces the display name for the card.
        let list = list_projects().expect("list");
        let p = list.iter().find(|p| p.name == "home-heating").unwrap();
        assert_eq!(p.display_name.as_deref(), Some("Home Heating"));
        // A safe name stays verbatim and records no display name.
        let cfg2 = create_project("MyApp", "", "starter").expect("create");
        assert_eq!(cfg2.name, "MyApp");
        assert_eq!(cfg2.display_name, None);
    }

    #[test]
    fn urban_scaffolds_json_escape_exotic_display_names() {
        // Display names are no longer restricted to is_safe_name, so both Urban
        // JSON scaffolds must escape quotes / backslashes / newlines or they
        // emit invalid JSON and a broken app.
        let nasty = "My \"App\"\nline\\two";
        let manifest = urban_manifest("my-app", nasty);
        let v: serde_json::Value =
            serde_json::from_str(&manifest).expect("manifest must be valid JSON");
        assert_eq!(v["name"], serde_json::json!(nasty));
        let page = urban_home_page("my-app", nasty);
        let v: serde_json::Value =
            serde_json::from_str(&page).expect("home page must be valid JSON");
        assert_eq!(v["title"], serde_json::json!(nasty));
    }

    #[test]
    fn create_and_rename_reject_case_insensitive_name_collisions() {
        let _g = lock();
        let _root = temp_root();
        // A safe verbatim name keeps its casing as the slug (is_safe_name allows
        // uppercase) and records no display name.
        create_project("MyApp", "", "starter").expect("create");
        // A differently-cased safe name slugs to a DISTINCT directory on a
        // case-sensitive filesystem, so the exact-case dir/ref checks miss it —
        // the case-insensitive guard must reject it (the server half of the
        // "client + server" uniqueness the console promises).
        let err = create_project("myapp", "", "starter")
            .err()
            .expect("case-insensitive slug collision should be rejected");
        assert!(err.contains("already exists"), "got: {err}");
        // An unrelated name is still free.
        create_project("cool-app-two", "", "starter").expect("unrelated name is free");
        // Renaming another project INTO an existing name (any case) is rejected
        // too — here the new slug "myapp" collides with "MyApp".
        create_project("plain", "", "starter").expect("create");
        let err = rename_project("plain", "MYAPP")
            .err()
            .expect("rename into an existing name (any case) should be rejected");
        assert!(err.contains("already exists"), "got: {err}");
    }

    #[test]
    fn rename_with_same_slug_updates_display_in_place() {
        let _g = lock();
        let _root = temp_root();
        // Spaced name → slug "cool-app", display "Cool App".
        let cfg = create_project("Cool App", "", "starter").expect("create");
        assert_eq!(cfg.name, "cool-app");
        assert_eq!(cfg.display_name.as_deref(), Some("Cool App"));
        // Renaming to a different spelling that slugs to the SAME directory is a
        // display-only edit — it must succeed in place, not error on the
        // self-directory existence check.
        let cfg = rename_project("cool-app", "COOL app").expect("display-only rename");
        assert_eq!(cfg.name, "cool-app");
        assert_eq!(cfg.display_name.as_deref(), Some("COOL app"));
        // Renaming to the bare slug clears the display name (display == slug).
        let cfg = rename_project("cool-app", "cool-app").expect("clear display");
        assert_eq!(cfg.name, "cool-app");
        assert_eq!(cfg.display_name, None);
    }

    #[test]
    fn rename_changes_only_case_of_the_slug() {
        let _g = lock();
        let _root = temp_root();
        create_project("MyApp", "", "starter").expect("create");
        // A case-only slug rename must succeed even on a case-insensitive
        // filesystem, where `to` (myapp) resolves to the project's own "MyApp"
        // directory and the naive `to.exists()` check would wrongly reject it.
        let cfg = rename_project("MyApp", "myapp").expect("case-only rename");
        assert_eq!(cfg.name, "myapp");
        // No duplicate project resulted — the single dir was renamed in place.
        let names: Vec<String> = list_projects()
            .expect("list")
            .into_iter()
            .map(|p| p.name)
            .collect();
        assert_eq!(
            names
                .iter()
                .filter(|n| n.eq_ignore_ascii_case("myapp"))
                .count(),
            1,
            "expected exactly one myapp project, got: {names:?}"
        );
    }

    #[test]
    fn rename_project_slugs_the_new_name_and_updates_the_display_name() {
        let _g = lock();
        let root = temp_root();
        create_project("plain", "", "starter").expect("create");
        let cfg = rename_project("plain", "Warm House").expect("rename");
        assert_eq!(cfg.name, "warm-house");
        assert_eq!(cfg.display_name.as_deref(), Some("Warm House"));
        assert!(root.join("warm-house").is_dir());
        assert!(!root.join("plain").exists());
        // Renaming back to a safe name clears the display name.
        let cfg = rename_project("warm-house", "plain2").expect("rename");
        assert_eq!(cfg.name, "plain2");
        assert_eq!(cfg.display_name, None);
    }

    #[test]
    fn project_templates_merges_pack_templates_after_builtins() {
        let _g = lock();
        let _root = temp_root();
        let ext = std::env::temp_dir().join(format!("nano-ext-tpl-test-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&ext);
        let pack = ext.join("nanobpm__app-embedded-nano");
        std::fs::create_dir_all(pack.join("templates/embedded-starter")).unwrap();
        std::fs::write(
            pack.join("nano-ide.ext.json"),
            r#"{"id":"embedded-nano","kind":"app","displayName":"Embedded μ-nano app",
                 "templates":[{"id":"embedded-starter","label":"Embedded engine"}]}"#,
        )
        .unwrap();
        // Also drop a pack that shadows a built-in id; the built-in must win.
        let shadow = ext.join("nanobpm__shadow");
        std::fs::create_dir_all(shadow.join("templates/starter")).unwrap();
        std::fs::write(
            shadow.join("nano-ide.ext.json"),
            r#"{"id":"shadow","kind":"app","displayName":"Shadow",
                 "templates":[{"id":"starter","label":"Should not appear"}]}"#,
        )
        .unwrap();
        // An example pack advertises itself as a template — no lang-pack
        // registration required. This is what a third-party publishing a
        // runnable example gets for free.
        let example = ext.join("nanobpm__example-thing");
        std::fs::create_dir_all(example.join("app")).unwrap();
        std::fs::write(
            example.join("nano-ide.ext.json"),
            r#"{"id":"thing-example","kind":"example","displayName":"Thing example",
                 "summary":"Runs the thing","appDir":"app"}"#,
        )
        .unwrap();

        unsafe { std::env::set_var("NANOBPMN_EXTENSIONS_DIR", &ext) };
        let templates = project_templates();
        unsafe { std::env::remove_var("NANOBPMN_EXTENSIONS_DIR") };
        let _ = std::fs::remove_dir_all(&ext);

        // Built-ins come first, in order, each tagged source=builtin and
        // carrying the card metadata (description + lang).
        for (i, t) in TEMPLATES.iter().enumerate() {
            assert_eq!(templates[i]["id"].as_str(), Some(t.id));
            assert_eq!(templates[i]["source"].as_str(), Some("builtin"));
            assert_eq!(templates[i]["description"].as_str(), Some(t.description));
            assert_eq!(templates[i]["lang"].as_str(), Some(t.lang));
        }
        // The pack template appears exactly once, after the built-ins, with pack provenance.
        let pack_hits: Vec<_> = templates
            .iter()
            .filter(|t| t["id"] == "embedded-starter")
            .collect();
        assert_eq!(pack_hits.len(), 1, "pack template should appear once");
        assert_eq!(pack_hits[0]["source"].as_str(), Some("pack"));
        assert_eq!(pack_hits[0]["pack"].as_str(), Some("embedded-nano"));
        assert_eq!(pack_hits[0]["label"].as_str(), Some("Embedded engine"));
        // An app pack with no `requires` implies the Deno runtime — mirrored
        // from create_project's cfg.lang derivation.
        assert_eq!(pack_hits[0]["lang"].as_str(), Some("deno"));
        // The shadowing pack's `starter` must not have overridden the built-in
        // (only one entry with id="starter", and its source is "builtin").
        let starter_hits: Vec<_> = templates.iter().filter(|t| t["id"] == "starter").collect();
        assert_eq!(starter_hits.len(), 1);
        assert_eq!(starter_hits[0]["source"].as_str(), Some("builtin"));
        // The example pack should appear as a template automatically, its
        // display name as the card title and its summary as the description.
        let ex_hits: Vec<_> = templates
            .iter()
            .filter(|t| t["id"] == "thing-example")
            .collect();
        assert_eq!(ex_hits.len(), 1, "example pack should auto-register");
        assert_eq!(ex_hits[0]["source"].as_str(), Some("pack"));
        assert_eq!(ex_hits[0]["pack"].as_str(), Some("thing-example"));
        assert_eq!(ex_hits[0]["label"].as_str(), Some("Thing example"));
        assert_eq!(ex_hits[0]["description"].as_str(), Some("Runs the thing"));
    }

    // --- Entrypoint resolution (#957) ---------------------------------------

    #[test]
    fn resolve_entrypoint_defaults_to_main_ts_without_overrides() {
        // No manifest, no explicit project-config main: the convention holds.
        let dir = scratch_dir("entry-default");
        let cfg = ProjectConfig::new("p", "");
        assert_eq!(resolve_entrypoint(&dir, &cfg), "main.ts");
    }

    #[test]
    fn resolve_entrypoint_honours_manifest_entrypoint() {
        // A path-linked app whose real entrypoint is src/main.ts declares it in
        // nano.app.json — no root main.ts shim, and no nanobpm.project.json.
        let dir = scratch_dir("entry-manifest");
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"app","name":"App","entrypoint":"src/main.ts"}"#,
        )
        .unwrap();
        let cfg = ProjectConfig::new("p", "");
        assert_eq!(resolve_entrypoint(&dir, &cfg), "src/main.ts");
    }

    #[test]
    fn resolve_entrypoint_rejects_absolute_manifest_entrypoint() {
        // A manifest entrypoint is resolved against the app root and handed to
        // the runtime, so an absolute path (which `Path::join` would honour
        // wholesale, escaping the root) must not be trusted — fall back.
        let dir = scratch_dir("entry-absolute");
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"app","name":"App","entrypoint":"/etc/passwd"}"#,
        )
        .unwrap();
        let cfg = ProjectConfig::new("p", "");
        assert_eq!(resolve_entrypoint(&dir, &cfg), "main.ts");
    }

    #[test]
    fn resolve_entrypoint_rejects_traversal_manifest_entrypoint() {
        // A `..`-traversing entrypoint could escape the app root — reject it and
        // fall back to the default rather than trust the manifest.
        let dir = scratch_dir("entry-traversal");
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"app","name":"App","entrypoint":"../../secrets.ts"}"#,
        )
        .unwrap();
        let cfg = ProjectConfig::new("p", "");
        assert_eq!(resolve_entrypoint(&dir, &cfg), "main.ts");
    }

    #[test]
    fn resolve_entrypoint_explicit_project_main_outranks_manifest() {
        // An explicit project-config main wins over the manifest entrypoint.
        let dir = scratch_dir("entry-precedence");
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"app","name":"App","entrypoint":"src/main.ts"}"#,
        )
        .unwrap();
        std::fs::write(
            dir.join(CONFIG_FILE),
            r#"{"name":"p","main":"app/entry.ts"}"#,
        )
        .unwrap();
        let mut cfg = ProjectConfig::new("p", "");
        cfg.main = "app/entry.ts".to_string();
        assert_eq!(resolve_entrypoint(&dir, &cfg), "app/entry.ts");
    }

    #[test]
    fn resolve_entrypoint_manifest_wins_when_project_config_lacks_main_key() {
        // A nanobpm.project.json that omits `main` (serde defaults it) does NOT
        // count as an explicit pin — the manifest entrypoint still travels.
        let dir = scratch_dir("entry-implicit");
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"app","name":"App","entrypoint":"src/main.ts"}"#,
        )
        .unwrap();
        std::fs::write(dir.join(CONFIG_FILE), r#"{"name":"p"}"#).unwrap();
        let cfg = ProjectConfig::new("p", "");
        assert_eq!(resolve_entrypoint(&dir, &cfg), "src/main.ts");
    }

    #[test]
    fn resolve_entrypoint_ignores_blank_manifest_entrypoint() {
        // A whitespace/empty entrypoint is treated as absent (falls back to main.ts).
        let dir = scratch_dir("entry-blank");
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"app","name":"App","entrypoint":"   "}"#,
        )
        .unwrap();
        let cfg = ProjectConfig::new("p", "");
        assert_eq!(resolve_entrypoint(&dir, &cfg), "main.ts");
    }

    #[test]
    fn resolve_entrypoint_blank_project_main_does_not_outrank_manifest() {
        // A `nanobpm.project.json` whose `main` is present but empty/whitespace
        // is NOT an explicit pin: it must not outrank a valid manifest
        // `entrypoint`, nor collapse to a confusing `entrypoint  not found`.
        let dir = scratch_dir("entry-blank-main");
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"app","name":"App","entrypoint":"src/main.ts"}"#,
        )
        .unwrap();
        std::fs::write(dir.join(CONFIG_FILE), r#"{"name":"p","main":"   "}"#).unwrap();
        // Mirror how the caller would deserialize a blank `main` from disk.
        let mut cfg = ProjectConfig::new("p", "");
        cfg.main = "   ".to_string();
        assert_eq!(resolve_entrypoint(&dir, &cfg), "src/main.ts");
    }

