    /// `gen_via_urban` is a public entrypoint, so it guards the `nano.app.json`
    /// shape itself: a legacy-shaped project is rejected before any `urban gen`
    /// spawn, so its `nano-generated/` is never clobbered with Urban outputs.
    #[cfg(unix)]
    #[tokio::test]
    #[allow(clippy::await_holding_lock)] // serialises on the shared PROJECTS_DIR env
    async fn gen_via_urban_rejects_a_legacy_shaped_project() {
        let _g = lock();
        let root = temp_root();
        let name = "legacyapp";
        let dir = root.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        // A legacy project (no nano.app.json) must not be delegated to urban.
        std::fs::write(dir.join("nanobpm.project.json"), "{}").unwrap();

        let err = gen_via_urban(name)
            .await
            .expect_err("legacy-shaped project should be rejected");
        assert!(
            err.contains("not an Urban-shaped app"),
            "unexpected error: {err}"
        );
    }

    // #522 slice (b): the `run_data_op` seam-routing invariant, exercised on the
    // pure decision function so it needs no filesystem/toolkit. Mirrors the
    // `regen_path` tests for `urban gen`.
    #[test]
    fn data_gateway_urban_app_prefers_urban_when_resolvable() {
        // An Urban-shaped app runs through `urban data` when the toolkit resolves;
        // otherwise it transitionally falls back to the embedded `data-cli.ts` so
        // the Data panel keeps working until the pack ships a `urban` with `data`
        // (slice c then removes the fallback).
        assert_eq!(
            data_gateway_path(true, true),
            DataGatewayPath::UrbanData,
            "urban app + toolkit → urban data"
        );
        assert_eq!(
            data_gateway_path(true, false),
            DataGatewayPath::Embedded,
            "urban app + no toolkit → transitional embedded fallback"
        );
    }

    #[test]
    fn data_gateway_legacy_app_always_uses_embedded() {
        // A legacy-shaped project keeps the embedded gateway regardless of whether
        // an urban binary happens to be resolvable on the host.
        assert_eq!(data_gateway_path(false, false), DataGatewayPath::Embedded);
        assert_eq!(data_gateway_path(false, true), DataGatewayPath::Embedded);
    }

    /// #522 slice (b) end-to-end: an Urban-shaped app whose toolkit resolves *and*
    /// carries the `data` op runs its data ops through `urban data` (spawned in the
    /// project dir) — the host never materialises or spawns the vendored
    /// `data-cli.ts`. A stub `urban` (via `NANOBPMN_URBAN_BIN`) advertises `urban
    /// data` in `--help` (so the capability probe passes), drains stdin and replies
    /// `{ok:true,…}`, standing in for the pack's toolkit so this needs no real
    /// `@nanobpm/urban`.
    #[cfg(unix)]
    #[tokio::test]
    #[allow(clippy::await_holding_lock)] // serialises on the shared PROJECTS_DIR env
    async fn run_data_op_routes_urban_app_to_urban_data() {
        let _g = lock();
        let root = temp_root();
        let name = "urban-data-app";
        let dir = root.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"urban-data-app"}"#,
        )
        .unwrap();

        // The stub advertises the `urban data` op in `--help` (so the capability
        // probe routes here), records its subcommand (`data`) + CWD, drains the
        // request on stdin, and emits the gateway's `{ok:true,…}` reply.
        let stub = root.join("urban-data-stub.sh");
        write_urban_stub(
            &stub,
            "case \"$*\" in *--help*) printf 'urban data — datasource op gateway\\n'; exit 0;; esac\ncat >/dev/null\nprintf '{\"ok\":true,\"routed\":\"urban-data\"}\\n'\n",
        );
        unsafe { std::env::set_var("NANOBPMN_URBAN_BIN", &stub) };

        let res = run_data_op(name, serde_json::json!({ "op": "schema" })).await;

        unsafe { std::env::remove_var("NANOBPMN_URBAN_BIN") };

        let val = res.expect("urban data routing should succeed");
        assert_eq!(
            val.get("routed").and_then(|v| v.as_str()),
            Some("urban-data"),
            "op was not served by the urban data stub: {val:?}"
        );
        // The stub was invoked as `urban data` in the project dir…
        let sentinel = std::fs::read_to_string(dir.join("urban-ran.txt")).unwrap();
        assert_eq!(
            sentinel.lines().next(),
            Some("data"),
            "urban not invoked with `data`: {sentinel:?}"
        );
        // …and the embedded `data-cli.ts` was never materialised for the Urban app.
        assert!(
            !dir.join(GEN_DIR).join("data-cli.ts").exists(),
            "embedded data-cli.ts must not be materialised for an Urban app"
        );
    }

    /// #522 slice (b): an Urban-shaped app whose resolved `urban` *predates* the
    /// `data` op (its `--help` advertises only `gen`/`run`) must fall back to the
    /// embedded gateway rather than be routed to a `urban data` it can't serve —
    /// additive + non-regressing, mirroring the `urban_supports_derive` gate. The
    /// capability probe is what makes this fallback happen, so the stub is never
    /// spawned as `data` in the project dir.
    #[cfg(unix)]
    #[tokio::test]
    #[allow(clippy::await_holding_lock)] // serialises on the shared PROJECTS_DIR env
    async fn run_data_op_falls_back_to_embedded_when_urban_lacks_data_op() {
        let _g = lock();
        let root = temp_root();
        let name = "urban-old-toolkit-app";
        let dir = root.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{"schemaVersion":1,"id":"urban-old-toolkit-app"}"#,
        )
        .unwrap();

        // A pre-`data` toolkit: `--help` lists only `gen`/`run`. Were it ever
        // (wrongly) routed to as `urban data`, it would write the `data` sentinel
        // in the project dir + reply with the urban marker — both asserted absent.
        let stub = root.join("urban-old-stub.sh");
        write_urban_stub(
            &stub,
            "case \"$*\" in *--help*) printf 'urban gen [--check]\\nurban run\\n'; exit 0;; esac\ncat >/dev/null\nprintf '{\"ok\":true,\"routed\":\"urban-data\"}\\n'\n",
        );
        unsafe { std::env::set_var("NANOBPMN_URBAN_BIN", &stub) };

        let res = run_data_op(name, serde_json::json!({ "op": "schema" })).await;

        unsafe { std::env::remove_var("NANOBPMN_URBAN_BIN") };

        // The capability probe saw no `urban data` in `--help`, so routing fell
        // back to the embedded gateway: the stub was never spawned as `data` in
        // the project dir (a `data` invocation sets `current_dir(&dir)` and would
        // have written the sentinel there — the `--help` probe writes elsewhere).
        assert!(
            !dir.join("urban-ran.txt").exists(),
            "urban stub must not be invoked as `data` when it lacks the data op"
        );
        // The response is therefore never the urban stub's marker reply (whether
        // the embedded path then succeeds or errors depends on the host runtime,
        // which is irrelevant to the routing decision under test).
        if let Ok(val) = &res {
            assert_ne!(
                val.get("routed").and_then(|v| v.as_str()),
                Some("urban-data"),
                "op must not be served by the urban stub when it lacks the data op"
            );
        }
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn pipe_data_gateway_surfaces_stdout_when_stderr_is_empty() {
        // A gateway that fails but writes its failure detail to stdout (not
        // stderr) must not have that detail hidden: the error should carry the
        // stdout text so the real cause is debuggable.
        let mut cmd = Command::new("sh");
        cmd.arg("-c").arg("printf 'boom-on-stdout'; exit 7");
        let err = pipe_data_gateway(cmd, &serde_json::json!({ "op": "schema" }))
            .await
            .expect_err("non-zero exit must be an error");
        match err {
            DataError::Gateway(msg) => {
                assert!(
                    msg.contains("boom-on-stdout"),
                    "stdout detail must surface in the error, got: {msg}"
                );
            }
            other => panic!("expected DataError::Gateway, got {other:?}"),
        }
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn pipe_data_gateway_includes_both_streams_when_stderr_is_present() {
        // When both streams carry text, stderr leads and stdout is appended so
        // neither is lost.
        let mut cmd = Command::new("sh");
        cmd.arg("-c")
            .arg("printf 'err-detail' 1>&2; printf 'out-detail'; exit 3");
        let err = pipe_data_gateway(cmd, &serde_json::json!({ "op": "schema" }))
            .await
            .expect_err("non-zero exit must be an error");
        match err {
            DataError::Gateway(msg) => {
                assert!(
                    msg.contains("err-detail") && msg.contains("out-detail"),
                    "both stderr and stdout must surface, got: {msg}"
                );
            }
            other => panic!("expected DataError::Gateway, got {other:?}"),
        }
    }

    #[test]
    fn gateway_parse_error_hints_at_flush_bug_on_pipe_boundary_truncation() {
        // A reply whose raw byte length is a positive multiple of the 64 KiB
        // pipe buffer (65536, 131072, …) is the truncated-gateway signature
        // (#1110 / nanobpm/nano-ide#549): the message must point at the flush
        // bug, not just echo the raw serde "EOF ... column 65536" error.
        let parse_err = serde_json::from_str::<serde_json::Value>("{\"a\":").unwrap_err();
        let msg = gateway_output_parse_error(&parse_err, PIPE_BUFFER_BYTES, "{\"a\":");
        assert!(
            msg.contains("pipe boundary") && msg.contains("process.exit()"),
            "boundary truncation must hint at the gateway flush bug, got: {msg}"
        );
        assert!(
            msg.contains(&PIPE_BUFFER_BYTES.to_string()),
            "message should report the truncation size, got: {msg}"
        );

        // A larger multiple (two full buffers) is the same signature.
        let msg2 = gateway_output_parse_error(&parse_err, PIPE_BUFFER_BYTES * 2, "{\"a\":");
        assert!(
            msg2.contains("pipe boundary"),
            "any positive multiple of the pipe buffer is a truncation, got: {msg2}"
        );
    }

    #[test]
    fn gateway_parse_error_keeps_raw_detail_for_ordinary_bad_json() {
        // Output that is not a 64 KiB multiple is a genuinely malformed reply:
        // keep the raw serde error and the offending text, no misleading flush
        // hint.
        let parse_err = serde_json::from_str::<serde_json::Value>("not json").unwrap_err();
        let msg = gateway_output_parse_error(&parse_err, 8, "not json");
        assert!(
            !msg.contains("pipe boundary"),
            "non-boundary lengths must not claim truncation, got: {msg}"
        );
        assert!(
            msg.contains("not json"),
            "raw offending text must be preserved, got: {msg}"
        );

        // Zero-length output is not a truncation either (empty reply / clean
        // exit with no stdout), so it must not be misattributed to a flush bug.
        let empty_err = serde_json::from_str::<serde_json::Value>("").unwrap_err();
        let empty_msg = gateway_output_parse_error(&empty_err, 0, "");
        assert!(
            !empty_msg.contains("pipe boundary"),
            "empty output must not be treated as boundary truncation, got: {empty_msg}"
        );

        // Defect-class guard: a genuinely malformed reply that happens to be
        // *exactly* a 64 KiB multiple must NOT be misattributed to the flush bug.
        // Truncation leaves a valid JSON prefix (an EOF-style parse error);
        // ordinary garbage yields a *syntax* error ("expected value"), so the
        // boundary length alone is not the signature — `is_eof()` must gate it.
        let syntax_err = serde_json::from_str::<serde_json::Value>("nope").unwrap_err();
        assert!(
            !syntax_err.is_eof(),
            "sanity: 'nope' is a syntax error, not EOF"
        );
        let boundary_syntax_msg =
            gateway_output_parse_error(&syntax_err, PIPE_BUFFER_BYTES, "nope");
        assert!(
            !boundary_syntax_msg.contains("pipe boundary"),
            "non-EOF error at a 64 KiB boundary must not claim truncation, got: {boundary_syntax_msg}"
        );

        // Defect-class guard: whitespace-only stdout that happens to be a 64 KiB
        // multiple trims to empty and yields an EOF error, but is NOT a truncated
        // JSON prefix (real flush-truncation leaves a valid, non-empty JSON
        // prefix). The `!trimmed.is_empty()` guard must keep it on the raw-error
        // path rather than misattributing it to the flush bug.
        let empty_eof = serde_json::from_str::<serde_json::Value>("").unwrap_err();
        assert!(empty_eof.is_eof(), "sanity: empty input is an EOF error");
        let whitespace_boundary_msg = gateway_output_parse_error(&empty_eof, PIPE_BUFFER_BYTES, "");
        assert!(
            !whitespace_boundary_msg.contains("pipe boundary"),
            "whitespace-only output at a 64 KiB boundary must not claim truncation, got: {whitespace_boundary_msg}"
        );
    }

    #[test]
    fn gateway_parse_error_caps_echoed_output_snippet() {
        // Defect-class guard: a genuinely malformed reply can be arbitrarily
        // large; the parse-error message must not echo it verbatim (unbounded
        // HTTP payloads / log lines / memory churn). The non-truncation path
        // caps the echoed text to a bounded snippet with an elision marker.
        let big = "x".repeat(GATEWAY_OUTPUT_SNIPPET_BYTES * 4);
        let parse_err = serde_json::from_str::<serde_json::Value>(&big).unwrap_err();
        // Length 8 (not a 64 KiB multiple) keeps this on the raw-detail path.
        let msg = gateway_output_parse_error(&parse_err, 8, &big);
        assert!(
            msg.len() < big.len(),
            "message must be shorter than the raw output, got {} vs {}",
            msg.len(),
            big.len()
        );
        assert!(
            msg.contains('…') && msg.contains(&format!("{} bytes total", big.len())),
            "capped message must mark elision and report the real length, got: {msg}"
        );

        // A short reply is echoed in full with no elision marker.
        let small = "nope";
        let small_err = serde_json::from_str::<serde_json::Value>(small).unwrap_err();
        let small_msg = gateway_output_parse_error(&small_err, 4, small);
        assert!(
            small_msg.contains(small) && !small_msg.contains('…'),
            "short output must be echoed verbatim without elision, got: {small_msg}"
        );
    }

    #[test]
    fn gateway_output_snippet_cuts_on_char_boundary() {
        // A multibyte char straddling the cap must not panic or split mid-char.
        let s = format!("{}€", "a".repeat(GATEWAY_OUTPUT_SNIPPET_BYTES - 1));
        let snippet = gateway_output_snippet(&s);
        assert!(
            snippet.ends_with("bytes total)"),
            "long input must be elided"
        );
        // A string exactly at the cap is returned untouched (borrowed).
        let exact = "a".repeat(GATEWAY_OUTPUT_SNIPPET_BYTES);
        assert!(
            matches!(
                gateway_output_snippet(&exact),
                std::borrow::Cow::Borrowed(_)
            ),
            "input at the cap must be borrowed unchanged"
        );
    }

    #[cfg(unix)]
    #[tokio::test]
    async fn pipe_data_gateway_flags_truncated_reply_at_pipe_boundary() {
        // End-to-end: a gateway whose stdout is a *valid JSON prefix* cut off at
        // exactly one 64 KiB pipe buffer — the real truncation signature in
        // #1110 / nanobpm/nano-ide#549 — must yield the flush-bug hint, not the
        // raw serde EOF error. The reply opens a JSON string (`{"a":"`) then runs
        // 65530 'a' bytes with no closing quote: an unterminated string that
        // serde reports as an EOF-style error, totalling exactly 65536 bytes.
        //
        // `tr '\000' 'a'` uses an octal NUL escape rather than `\0`: on BSD/macOS
        // `tr`, `\0` is not a reliable spelling for NUL and can leave the bytes
        // unchanged, which flips the failure mode to an invalid-control-character
        // error instead of EOF. The octal form is portable across GNU and BSD tr.
        let mut cmd = Command::new("sh");
        cmd.arg("-c")
            .arg("printf '{\"a\":\"'; head -c 65530 /dev/zero | tr '\\000' 'a'");
        let err = pipe_data_gateway(cmd, &serde_json::json!({ "op": "schema" }))
            .await
            .expect_err("unparseable output must be an error");
        match err {
            DataError::Gateway(msg) => {
                assert!(
                    msg.contains("pipe boundary") && msg.contains("process.exit()"),
                    "truncated reply must hint at the gateway flush bug, got: {msg}"
                );
            }
            other => panic!("expected DataError::Gateway, got {other:?}"),
        }
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)] // serialises on the shared PROJECTS_DIR env; guard must span the run_data_op await
    async fn domaintypes_op_resolves_a_composed_shape_into_the_registry() {
        let _g = lock();
        if workers::usable_node().is_none() && workers::find_deno().is_none() {
            eprintln!("skipping: no JS runtime (Node >= 22.6 or Deno) installed");
            return;
        }
        let root = temp_root();
        let name = "shapes";
        let dir = root.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        // Leaf entities the shape composes from: a manifest `Order` type and a DB
        // `customers` table (created below), plus a scalar `extend`.
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{
                "data": { "default": "app", "sources": {
                    "app": { "driver": "sqlite", "url": "file:./app.db" }
                } },
                "types": {
                    "Order": { "fields": {
                        "item": { "type": "string" },
                        "qty": { "type": "integer" }
                    } }
                }
            }"#,
        )
        .unwrap();
        write_shape_model(
            &dir,
            r#"<nano:shape id="ApprovedOrder" name="Approved order">
                 <nano:carry ref="Order" />
                 <nano:project ref="customers" fields="name" />
                 <nano:extend name="approved" type="boolean" />
               </nano:shape>"#,
        );
        ensure_project_sdk(name).unwrap();

        run_data_op(
            name,
            serde_json::json!({ "op": "exec",
                "sql": "CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL)" }),
        )
        .await
        .expect("create table");

        let dt = run_data_op(name, serde_json::json!({ "op": "domaintypes" }))
            .await
            .expect("domaintypes");
        let text = dt["text"].as_str().unwrap();
        // The composed shape lands in DomainTypes as a first-class entry, folding
        // carried `Order` fields, the projected `customers.name`, and the extend.
        assert!(
            text.contains("\"ApprovedOrder\": {"),
            "shape missing: {text}"
        );
        assert!(text.contains("item: string;"));
        assert!(text.contains("qty: number;"));
        assert!(text.contains("name: string;"));
        assert!(text.contains("approved: boolean;"));
        // No diagnostics on a clean resolution.
        let diags = dt["shapeDiagnostics"].as_array().unwrap();
        assert!(diags.is_empty(), "unexpected diagnostics: {diags:?}");
    }

    #[tokio::test]
    #[allow(clippy::await_holding_lock)] // serialises on the shared PROJECTS_DIR env; guard must span the run_data_op await
    async fn domaintypes_op_consumes_model_meta_and_writes_the_fuse_cache() {
        let _g = lock();
        if workers::usable_node().is_none() && workers::find_deno().is_none() {
            eprintln!("skipping: no JS runtime (Node >= 22.6 or Deno) installed");
            return;
        }
        let root = temp_root();
        let name = "meta-fuse";
        let dir = root.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{ "data": { "default": "app", "sources": {
                    "app": { "driver": "sqlite", "url": "file:./app.db" }
                } },
                "types": { "Order": { "fields": { "item": { "type": "string" } } } }
            }"#,
        )
        .unwrap();
        // A model that carries one composed shape plus two model-level `nano:meta`
        // siblings of the `nano:shapes` container (ADR 0040 §5).
        let procs = dir.join("resources").join("processes");
        std::fs::create_dir_all(&procs).unwrap();
        std::fs::write(
            procs.join("orders.bpmn"),
            r#"<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:nano="https://nanobpm.io/schema/shapes/1.0" id="d">
  <bpmn:process id="orders" isExecutable="true">
    <bpmn:extensionElements>
      <nano:shapes><nano:shape id="ApprovedOrder"><nano:carry ref="Order" /></nano:shape></nano:shapes>
      <nano:meta key="classification" value="internal" />
      <nano:meta key="owner" value="ops" />
      <nano:meta key="owner" value="sre" />
    </bpmn:extensionElements>
  </bpmn:process>
</bpmn:definitions>"#,
        )
        .unwrap();
        ensure_project_sdk(name).unwrap();

        let dt = run_data_op(name, serde_json::json!({ "op": "domaintypes" }))
            .await
            .expect("domaintypes");

        // The typed metadata accessor (`@nanobpm/meta`) is emitted + materialised.
        assert_eq!(dt["metaPath"], "nano-generated/meta.ts");
        let meta_ts = dt["meta"].as_str().unwrap();
        assert!(
            meta_ts.contains("classification: string;"),
            "meta.ts: {meta_ts}"
        );
        assert!(meta_ts.contains(r#"m["classification"] = "internal";"#));
        // Duplicate key: the last declaration wins in the folded accessor.
        assert!(
            meta_ts.contains(r#"m["owner"] = "sre";"#),
            "last-wins fold: {meta_ts}"
        );
        assert!(
            !meta_ts.contains(r#"m["owner"] = "ops";"#),
            "overridden value must not be emitted: {meta_ts}"
        );
        // The accessor dict is null-prototype (safe for user-authored keys).
        assert!(
            meta_ts.contains("Object.create(null)"),
            "null-proto: {meta_ts}"
        );
        assert!(meta_ts.contains("export function meta<K extends keyof AppMeta>"));
        let meta_disk = std::fs::read_to_string(dir.join("nano-generated/meta.ts")).unwrap();
        assert_eq!(meta_disk, meta_ts);

        // The structured fuse cache (`domain.json`) is emitted + materialised, and
        // parses with an `inputsHash`, the metadata, and the composed-shape entity.
        assert_eq!(dt["domainModelPath"], "nano-generated/domain.json");
        let dm: serde_json::Value =
            serde_json::from_str(dt["domainModel"].as_str().unwrap()).unwrap();
        assert!(dm["inputsHash"].as_str().is_some_and(|h| !h.is_empty()));
        let meta_entries = dm["meta"].as_array().unwrap();
        assert!(meta_entries.iter().any(|m| m["key"] == "classification"
            && m["value"] == "internal"
            && m["process"] == "orders"));
        let entities = dm["entities"].as_array().unwrap();
        assert!(entities.iter().any(|e| e["id"] == "ApprovedOrder"
            && e["kind"] == "shape"
            && e["provenance"] == "model:orders"));
        // The DB/manifest provenance is distinguished (folding does not blur it).
        assert!(
            entities
                .iter()
                .any(|e| e["id"] == "Order" && e["kind"] == "type")
        );
        let dm_disk = std::fs::read_to_string(dir.join("nano-generated/domain.json")).unwrap();
        assert_eq!(dm_disk, dt["domainModel"].as_str().unwrap());
    }

    /// A user-authored metadata key of `__proto__` must round-trip: `foldMeta` and the
    /// emitted accessor are null-prototype dicts, so `__proto__` becomes an own data
    /// property (not a silently-dropped prototype-setter write) in both `meta.ts` and
    /// `domain.json`. Guards the prototype-pollution hardening (ADR 0040 §5).
    #[tokio::test]
    #[allow(clippy::await_holding_lock)] // serialises on the shared PROJECTS_DIR env
    async fn domaintypes_meta_round_trips_a_proto_key() {
        let _g = lock();
        if workers::usable_node().is_none() && workers::find_deno().is_none() {
            eprintln!("skipping: no JS runtime (Node >= 22.6 or Deno) installed");
            return;
        }
        let root = temp_root();
        let name = "meta-proto";
        let dir = root.join(name);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(
            dir.join("nano.app.json"),
            r#"{ "data": { "default": "app", "sources": {
                    "app": { "driver": "sqlite", "url": "file:./app.db" } } } }"#,
        )
        .unwrap();
        let procs = dir.join("resources").join("processes");
        std::fs::create_dir_all(&procs).unwrap();
        std::fs::write(
            procs.join("p.bpmn"),
            r#"<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"
                  xmlns:nano="https://nanobpm.io/schema/shapes/1.0" id="d">
  <bpmn:process id="p" isExecutable="true">
    <bpmn:extensionElements>
      <nano:meta key="__proto__" value="polluted" />
    </bpmn:extensionElements>
  </bpmn:process>
</bpmn:definitions>"#,
        )
        .unwrap();
        ensure_project_sdk(name).unwrap();

        let dt = run_data_op(name, serde_json::json!({ "op": "domaintypes" }))
            .await
            .expect("domaintypes");
        // The dangerous key survives the fold and is assigned via bracket notation.
        let meta_ts = dt["meta"].as_str().unwrap();
        assert!(
            meta_ts.contains(r#"m["__proto__"] = "polluted";"#),
            "__proto__ must round-trip as an own property: {meta_ts}"
        );
        // …and appears in the structured cache exactly once.
        let dm: serde_json::Value =
            serde_json::from_str(dt["domainModel"].as_str().unwrap()).unwrap();
        let hits = dm["meta"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|m| m["key"] == "__proto__" && m["value"] == "polluted")
            .count();
        assert_eq!(hits, 1, "domain.json meta: {}", dm["meta"]);
    }

